from pathlib import Path
p=Path('src/App.tsx')
s=p.read_text(encoding='utf-8')
start=s.index('  return <div className="app-shell">')
end=s.index('    {view === "home" &&', start)
replacement='''  return <div className={`app-shell ${subject === "math" ? "math-subject" : "english-subject"}`} data-subject={subject}>
    <header className="topbar"><div className="brand"><span className="brand-mark">{subject === "math" ? "数" : "知"}</span><div><strong>{subject === "math" ? "高考数学自习室" : "搭配自习室"}</strong><small>{subject === "math" ? "二级结论与逻辑转化" : "高中英语连续训练"}</small></div></div><nav>{subject === "math" ? <><button onClick={() => setMathView("home")}>今日训练</button><button onClick={() => setMathView("mistakes")}>错题强化 <b>{mathMistakes.length}</b></button><button onClick={() => setMathView("library")}>题库</button><button onClick={() => setMathView("report")}>报告与存档</button></> : <><button className={view === "home" ? "active" : ""} onClick={() => setView("home")}>今日训练</button><button className={view === "mistakes" ? "active" : ""} onClick={() => setView("mistakes")}>错题强化 <b>{mistakes.length}</b></button><button className={view === "library" ? "active" : ""} onClick={() => setView("library")}>题库</button><button className={view === "report" ? "active" : ""} onClick={() => setView("report")}>报告与存档</button>}</nav><div className="subject-switch" role="group" aria-label="切换学习科目"><button aria-pressed={subject === "english"} onClick={() => setActiveSubject("english")}>英语</button><button aria-pressed={subject === "math"} onClick={() => setActiveSubject("math")}>数学</button></div><span className="status-dot">● 本地保存</span></header>
    {subject === "math" ? <>
      {mathView === "home" && <main className="page"><section className="hero"><div><p className="eyebrow">GAOKAO MATHEMATICS</p><h1>记住关键条件，<em>把二级结论用准。</em></h1><p>首期覆盖积化和差与充分必要条件，关注结论推导和易错转化；不是完整高考题库。</p><button className="primary large" onClick={() => startMath()}>开始数学训练（{mathQuestions.length}题）</button></div></section><section className="mode-grid"><article onClick={() => startMath(mathQuestions.filter(q => q.topic === "trigonometric-identities").map(q => q.id))}><h2>三角恒等变换</h2><p>积化和差、符号和系数辨析</p></article><article onClick={() => startMath(mathQuestions.filter(q => q.topic === "necessary-sufficient").map(q => q.id))}><h2>充分必要条件</h2><p>蕴含方向、逆命题与逆否命题</p></article><article onClick={() => setMathView("mistakes")}><h2>错题强化 · {mathMistakes.length}</h2></article><article onClick={() => setMathView("library")}><h2>数学题库 · {mathQuestions.length}</h2></article><article onClick={() => setMathView("report")}><h2>学习报告与存档</h2></article></section></main>}
      {mathView === "quiz" && currentMath && <main className="quiz page"><div className="quiz-head"><span className="pill">{mathTopicNames[currentMath.topic]}</span><span>{mathIndex+1} / {mathQueue.length}</span></div><section className="question-panel"><div className="math-conditions">适用条件：{currentMath.conditions.join("；")}</div><h1 className="math-prompt">{currentMath.prompt}</h1>{currentMath.type === "choice" ? <div className="options">{currentMath.options?.map(o => <button key={o.id} className={`option ${mathAnswer===o.id?"selected":""}`} disabled={!!mathFeedback} onClick={() => setMathAnswer(o.id)}><span>{o.id}</span>{o.text}</button>)}</div> : <input className="answer-input" value={mathAnswer} onChange={e => setMathAnswer(e.target.value)} placeholder="输入数学式…"/>}{mathFeedback && <div className={`feedback ${mathFeedback.correct?"success":"error"}`}><strong>{mathFeedback.correct?"回答正确":"再巩固一下"}</strong><p>正确答案：{currentMath.type==="choice"?currentMath.options?.find(o=>o.id===currentMath.answer)?.text:currentMath.answer}</p><ol>{currentMath.explanation.map(step=><li key={step}>{step}</li>)}</ol><p>易错点：{currentMath.pitfall}</p></div>}</section><div className="control-bar"><button className="ghost" onClick={() => setMathView("home")}>退出</button>{mathFeedback?<button className="primary" onClick={nextMath}>下一题 / 完成</button>:<button className="primary" disabled={!mathAnswer} onClick={submitMath}>提交答案</button>}</div></main>}
      {mathView === "mistakes" && <main className="page list-page"><h1>数学错题强化</h1>{mathMistakes.map(q=><article key={q.id}><strong>{q.prompt}</strong><button onClick={()=>startMath([q.id])}>重练</button></article>)}</main>}
      {mathView === "library" && <main className="page list-page"><h1>数学题库 · {mathQuestions.length} 道</h1>{mathQuestions.map(q=><article key={q.id}><span>{mathTopicNames[q.topic]}</span><p>{q.prompt}</p><button onClick={()=>toggleMathFavorite(q.id)}>{mathStore.favorites.includes(q.id)?"★":"☆"}</button><small>{q.pitfall}</small></article>)}</main>}
      {mathView === "report" && <main className="page list-page"><h1>数学学习报告与存档</h1><p>记录 {mathStore.records.length} · 正确 {mathStore.records.filter(r=>r.correct).length}</p><button className="primary" onClick={downloadMathBackup}>导出数学存档</button><label className="file-import">导入数学存档<input type="file" accept=".json,application/json" onChange={e=>{const f=e.target.files?.[0];if(f)importMathBackup(f);}}/></label><p>{mathImportMessage}</p></main>}
    </> : <>
    {view === "home" &&'''
s=s[:start]+replacement+s[end+len('    {view === "home" &&'):]
p.write_text(s,encoding='utf-8')
